package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTax decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxRec TaxRec

var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }

func modStore(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep only low-order digits that fit: modulo 10^(intDigits+scale)
	total := intDigits + int(scale)
	mod := decimal.New(1, int32(total)) // 10^total
	neg := d.IsNegative()
	a := d.Abs()
	// a is already at correct scale (rounded/truncated); get scaled integer
	scaled := a.Shift(scale).Truncate(0)
	q := scaled.Mod(mod)
	v := q.Shift(-scale)
	if neg && !q.IsZero() {
		v = v.Neg()
	}
	return v
}

func parseIncomeField(s string) decimal.Decimal {
	// DISPLAY numeric: digits only, implied decimal 2
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.New(0, -2)
	}
	// collect digits; ignore '.' if present (should not occur)
	digits := make([]byte, 0, len(t))
	dotSeen := false
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			digits = append(digits, c)
		} else if c == '.' && !dotSeen {
			// if explicit dot present, treat as decimal point: handle separately
			dotSeen = true
			// mark position
			digits = append(digits, '.')
		}
	}
	if dotSeen {
		// parse with explicit point
		ds := string(digits)
		d, err := decimal.NewFromString(ds)
		if err != nil {
			return decimal.Zero
		}
		return d
	}
	if len(digits) == 0 {
		return decimal.New(0, -2)
	}
	var n int64 = 0
	for _, c := range digits {
		n = n*10 + int64(c-'0')
	}
	return decimal.New(n, -2)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(val decimal.Decimal, pic string) string {
	// count integer placeholders and fraction placeholders
	dotPos := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = pic[:dotPos]
		fracPic = pic[dotPos+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intPlace := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intPlace++
		}
	}
	fracPlace := 0
	for i := 0; i < len(fracPic); i++ {
		if fracPic[i] == 'Z' || fracPic[i] == '9' {
			fracPlace++
		}
	}
	neg := val.IsNegative()
	abs := val.Abs()
	// truncate toward zero to fracPlace (MOVE semantics; values already at scale)
	scaled := abs.Shift(int32(fracPlace)).Truncate(0)
	s := scaled.String()
	// scaled String may contain decimal point if negative exponent? Truncate(0) ensures integer
	// remove possible sign / exponent
	if idx := strings.Index(s, "."); idx >= 0 {
		s = s[:idx]
	}
	if idx := strings.IndexAny(s, "eE"); idx >= 0 {
		// fallback: should not happen
		s = "0"
	}
	s = strings.TrimSpace(s)
	if s == "" || s == "-" {
		s = "0"
	}
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	totalDigits := intPlace + fracPlace
	if len(s) < totalDigits {
		s = strings.Repeat("0", totalDigits-len(s)) + s
	} else if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	intDigitsStr := ""
	fracDigitsStr := ""
	if totalDigits == 0 {
		intDigitsStr = ""
		fracDigitsStr = ""
	} else {
		if intPlace > 0 {
			intDigitsStr = s[:intPlace]
		}
		if fracPlace > 0 {
			fracDigitsStr = s[intPlace:]
		}
	}
	// types of integer placeholders in order
	intTypes := make([]byte, 0, intPlace)
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intTypes = append(intTypes, intPic[i])
		}
	}
	// determine first non-zero
	k := intPlace // index of first nonzero
	for i := 0; i < intPlace; i++ {
		if intDigitsStr[i] != '0' {
			k = i
			break
		}
	}
	dispDigits := make([]byte, intPlace)
	for i := 0; i < intPlace; i++ {
		if i < k && intTypes[i] == 'Z' {
			dispDigits[i] = ' '
		} else if i < k && intTypes[i] == '9' {
			dispDigits[i] = intDigitsStr[i] // '0'
		} else {
			dispDigits[i] = intDigitsStr[i]
		}
	}
	// build integer part with commas
	var intOut []byte
	di := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			intOut = append(intOut, dispDigits[di])
			di++
		} else if c == ',' {
			// if all digits to left are spaces, comma -> space
			allSpace := true
			for j := 0; j < di; j++ {
				if dispDigits[j] != ' ' {
					allSpace = false
					break
				}
			}
			if allSpace {
				intOut = append(intOut, ' ')
			} else {
				intOut = append(intOut, ',')
			}
		} else {
			intOut = append(intOut, c)
		}
	}
	var fracOut []byte
	if dotPos >= 0 {
		fracOut = append(fracOut, '.')
		fi := 0
		for i := 0; i < len(fracPic); i++ {
			c := fracPic[i]
			if c == 'Z' || c == '9' {
				var ch byte
				if fi < len(fracDigitsStr) {
					ch = fracDigitsStr[fi]
				} else {
					ch = '0'
				}
				fracOut = append(fracOut, ch)
				fi++
			} else if c == ',' {
				fracOut = append(fracOut, ',')
			} else {
				fracOut = append(fracOut, c)
			}
		}
	}
	out := string(intOut) + string(fracOut)
	// handle negative: replace last leading space with '-' if possible? COBOL would show minus.
	// For non-negative this is exact. Implement simple: if negative, put '-' at leftmost space before digit, else overwrite first char.
	if neg {
		// find rightmost space before digits in intOut
		placed := false
		for i := len(intOut) - 1; i >= 0; i-- {
			if intOut[i] == ' ' {
				// ensure there is a digit to the right that is not space
				hasDigit := false
				for j := i + 1; j < len(intOut); j++ {
					if intOut[j] >= '0' && intOut[j] <= '9' {
						hasDigit = true
						break
					}
				}
				if hasDigit {
					intOut[i] = '-'
					placed = true
					break
				}
			}
		}
		if !placed && len(intOut) > 0 {
			intOut[0] = '-'
		}
		out = string(intOut) + string(fracOut)
	}
	// ensure exact width of picture
	if len(out) < len(pic) {
		out = strings.Repeat(" ", len(pic)-len(out)) + out
	} else if len(out) > len(pic) {
		out = out[len(out)-len(pic):]
	}
	return out
}

func formatCount(c int64) string {
	v := c % 1000
	if v < 0 {
		v += 1000
	}
	return fmt.Sprintf("%03d", v)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	taxRec.TrId = line[0:5]
	taxRec.TrIncome = parseIncomeField(line[5:13])
}

func PROCESSPARA() {
	lim1 := decimal.New(1000000, -2) // 10000.00
	lim2 := decimal.New(4000000, -2) // 40000.00
	r10, _ := decimal.NewFromString("0.10")
	r20, _ := decimal.NewFromString("0.20")
	r30, _ := decimal.NewFromString("0.30")
	c1000, _ := decimal.NewFromString("1000.00")
	c7000, _ := decimal.NewFromString("7000.00")
	if taxRec.TrIncome.Cmp(lim1) <= 0 {
		v := taxRec.TrIncome.Mul(r10)
		v = v.Round(2)
		WsTax = modStore(v, 7, 2)
	} else {
		if taxRec.TrIncome.Cmp(lim2) <= 0 {
			v := c1000.Add(taxRec.TrIncome.Sub(lim1).Mul(r20))
			v = v.Round(2)
			WsTax = modStore(v, 7, 2)
		} else {
			v := c7000.Add(taxRec.TrIncome.Sub(lim2).Mul(r30))
			v = v.Round(2)
			WsTax = modStore(v, 7, 2)
		}
	}
	vn := taxRec.TrIncome.Sub(WsTax).Truncate(2)
	WsNet = modStore(vn, 7, 2)
	WsTotalTax = modStore(WsTotalTax.Add(WsTax).Truncate(2), 9, 2)
	WsCount = (WsCount + 1) % 1000
	// negative modulo guard (counts non-negative)
	if WsCount < 0 {
		WsCount += 1000
	}
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Fprintln(os.Stdout, taxRec.TrId+" "+WsIncEd+" "+WsTaxEd+" "+WsNetEd)
	READPARA()
}

func MAINPARA() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewReader(f)
	inputLines = nil
	for {
		raw, err := scanner.ReadString('\n')
		hasData := len(raw) > 0
		if hasData {
			// strip only trailing \r\n
			if strings.HasSuffix(raw, "\r\n") {
				raw = raw[:len(raw)-2]
			} else if strings.HasSuffix(raw, "\n") {
				raw = raw[:len(raw)-1]
			} else if strings.HasSuffix(raw, "\r") {
				raw = raw[:len(raw)-1]
			}
			inputLines = append(inputLines, raw)
		}
		if err != nil {
			break
		}
	}
	f.Close()
	inputIdx = 0
	inputOpen = true
	_ = inputOpen
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE TAX-FILE (already closed)
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	fmt.Fprintln(os.Stdout, "TAXPAYERS: "+formatCount(WsCount)+" TOTAL TAX: "+WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.New(0, 0)
	WsNet = decimal.New(0, 0)
	WsTotalTax = decimal.New(0, 0)
	WsCount = 0
	MAINPARA()
}
